            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Yahuda ne yaptıysa kendine yaptı dedi Hikmet, İsa için üzücü olan, Yahuda'nın ihaneti değildi: neden yaşadığını hiç bilmeyen bu zavallı hain, neden intihar ettiğini de anlayamadan ölüp gitmişti. İsa işte buna üzülüyordu.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Bir şeyden yana değiliz ki Hayri dedi hüzünle, Bir parti kuralım. Şoför Hayri şiddetle içini çekti: Ah bir olabilseydik ağabeyciğim, biz de bir şeyden yana olabilseydik. Tuğrul, Ya da bir şeyler bizden yana olsaydı, diye tamamladı.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Beni anlamıyorlardı. Zarar yok. Zaten beni, daha kimler anlamadı.", Author = "Oğuz Atay" },
