            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "İyi şeyler birdenbire olur; bu kadar bekletmez insanı. Sürüncemede kalan heyecanlardan ancak kötü şeyler çıkar. Ya da hiçbir şey çıkmaz.", Author = "Oğuz Atay" },
